findings.recommendation:
Use an object instead of Map when keys are string agent names (no ordering needed):

const counts: Record<AgentName, number> = {}
const firstReason: Partial<Record<AgentName, string>> = {}
for (const r of withPolicy) {
  for (const agent of r.policy!.agentsSkipped) {
    const current = counts[agent] ?? 0
    counts[agent] = current + 1
    if (!firstReason[agent]) firstReason[agent] = r.policy!.reason[agent]
  }
}

Use Map to accumulate unique files, then sort once at the end:

const merged: Partial<Record<AgentName, string[]>> = {}
for (const r of results) {
  for (const [agent, files] of Object.entries(r.filteredFiles ?? {})) {
    if (!merged[agent]) merged[agent] = []
    // Use object as temp Set to dedup
    const existingMap = new Map<string,boolean>()
    for (const f of [...(merged[agent] ?? []), ...(files ?? [])]) {
      if (!existingMap.has(f)) {
        existingMap.set(f, true)
        merged[agent].push(f)
      }
    }
  }
}
// Sort once after merging all chunks
for (const agent of Object.keys(merged)) {
  merged[agent].sort()
}
